import clsx from 'clsx';
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useEnv } from '@/context/EnvContext';
import { useBookDataStore } from '@/store/bookDataStore';
import { useBookProgress } from '@/store/readerProgressStore';
import { useTranslation } from '@/hooks/useTranslation';
import type { TranslationFunc } from '@/hooks/useTranslation';
import { StatisticsDb } from '@/services/statistics/statisticsDb';

// One segment per ~2% of the book: enough resolution to show pace changes
// without the strip turning into per-page noise on long books.
const SEGMENT_COUNT = 50;
// Re-read the stats DB while reading so the current session shows up.
const REFRESH_INTERVAL_MS = 30_000;

/** "35m 46s" — minute+second precision, never a long decimal. */
const formatHeatTotal = (totalSeconds: number, _: TranslationFunc): string => {
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = Math.round(totalSeconds % 60);
  // Rounding can carry 59.6s into a full minute.
  if (seconds >= 60) return _('{{minutes}}m 0s', { minutes: minutes + 1 });
  return _('{{minutes}}m {{seconds}}s', { minutes, seconds });
};

interface ReadingHeatmapProgressProps {
  bookKey: string;
  /** Current position, 0..1. */
  fraction: number;
  /** Called with the target fraction (0..1) while the strip is dragged. */
  onSeek: (fraction: number) => void;
  rtl?: boolean;
  className?: string;
}

/**
 * The reader footer's progress control as a reading-heat strip: each segment's
 * blue intensity is the time spent reading that slice of the book (from the
 * statistics DB), with the current position as a draggable handle. Books with
 * no recorded statistics degrade to a plain track.
 */
const ReadingHeatmapProgress: React.FC<ReadingHeatmapProgressProps> = ({
  bookKey,
  fraction,
  onSeek,
  rtl = false,
  className,
}) => {
  const _ = useTranslation();
  const { appService } = useEnv();
  const getBookData = useBookDataStore((s) => s.getBookData);
  const progress = useBookProgress(bookKey);
  const bookMd5 = getBookData(bookKey)?.book?.hash;
  const totalPages = progress?.pageinfo?.total ?? 0;

  const [pageSeconds, setPageSeconds] = useState<Map<number, number>>(new Map());
  const [totalSeconds, setTotalSeconds] = useState(0);
  const [dragging, setDragging] = useState(false);
  const stripRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!appService || !bookMd5) return;
    let cancelled = false;
    const load = async () => {
      try {
        const db = await StatisticsDb.open(appService);
        const book = await db.getBookByMd5(bookMd5);
        if (!book || cancelled) return;
        const map = await db.getPageDurationMap(book.id);
        if (cancelled) return;
        setPageSeconds(map);
        setTotalSeconds(book.total_read_time);
      } catch (err) {
        // Best-effort telemetry: never break the footer over a stats read.
        console.warn('[stats] reading heatmap failed:', err);
      }
    };
    void load();
    const timer = setInterval(load, REFRESH_INTERVAL_MS);
    return () => {
      cancelled = true;
      clearInterval(timer);
    };
  }, [appService, bookMd5]);

  const segments = useMemo(() => {
    const segs = new Array<number>(SEGMENT_COUNT).fill(0);
    const total = Math.max(totalPages, 1);
    for (const [page, secs] of pageSeconds) {
      const idx = Math.min(
        SEGMENT_COUNT - 1,
        Math.max(0, Math.floor(((page - 1) / total) * SEGMENT_COUNT)),
      );
      segs[idx]! += secs;
    }
    const max = Math.max(...segs, 1);
    // A floor keeps barely-read segments visible instead of vanishing.
    return segs.map((v) => (v > 0 ? Math.max(0.15, v / max) : 0));
  }, [pageSeconds, totalPages]);

  const hasData = pageSeconds.size > 0;
  // RTL books start on the right, so the handle mirrors across the strip.
  const handleFraction = rtl ? 1 - fraction : fraction;

  const seekFromClientX = useCallback(
    (clientX: number) => {
      const el = stripRef.current;
      if (!el) return;
      const rect = el.getBoundingClientRect();
      if (rect.width <= 0) return;
      const raw = Math.min(1, Math.max(0, (clientX - rect.left) / rect.width));
      onSeek(rtl ? 1 - raw : raw);
    },
    [onSeek, rtl],
  );

  const handlePointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    e.preventDefault();
    setDragging(true);
    e.currentTarget.setPointerCapture(e.pointerId);
    seekFromClientX(e.clientX);
  };

  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!dragging) return;
    seekFromClientX(e.clientX);
  };

  const endDrag = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!dragging) return;
    setDragging(false);
    if (e.currentTarget.hasPointerCapture(e.pointerId)) {
      e.currentTarget.releasePointerCapture(e.pointerId);
    }
  };

  return (
    <div className={clsx('flex min-w-0 flex-1 flex-col justify-center gap-1', className)}>
      <div className='flex items-center justify-between text-[11px] leading-none text-base-content/70'>
        <span>{_('Reading Heat Progress')}</span>
        {hasData && (
          <span className='tabular-nums'>
            {_('Total {{time}}', { time: formatHeatTotal(totalSeconds, _) })}
          </span>
        )}
      </div>
      <div
        ref={stripRef}
        role='slider'
        tabIndex={0}
        aria-label={_('Jump to Location')}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={Math.round(fraction * 100)}
        dir='ltr'
        className='relative h-3 cursor-pointer touch-none rounded-full bg-blue-500/10'
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={endDrag}
        onPointerCancel={endDrag}
        onKeyDown={(e) => {
          if (e.key === 'ArrowLeft' || e.key === 'ArrowDown') {
            e.preventDefault();
            onSeek(Math.max(0, fraction - 0.02));
          } else if (e.key === 'ArrowRight' || e.key === 'ArrowUp') {
            e.preventDefault();
            onSeek(Math.min(1, fraction + 0.02));
          }
        }}
      >
        {hasData && (
          <div className='pointer-events-none absolute inset-0 flex gap-px overflow-hidden rounded-full'>
            {segments.map((value, i) => (
              <div
                key={i}
                className='h-full flex-1 rounded-full'
                style={{ backgroundColor: `rgba(59, 130, 246, ${0.2 + 0.75 * value})` }}
              />
            ))}
          </div>
        )}
        <div
          className={clsx(
            'pointer-events-none absolute top-1/2 h-3 w-3 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-blue-500 bg-base-100 shadow-sm transition-transform',
            dragging && 'scale-125',
          )}
          style={{ left: `${handleFraction * 100}%` }}
        />
      </div>
    </div>
  );
};

export default ReadingHeatmapProgress;
