import React, { useEffect, useState } from 'react';
import Popup from '@/components/Popup';
import { Position } from '@/utils/sel';
import { useEnv } from '@/context/EnvContext';
import { useReaderStore } from '@/store/readerStore';
import { useBookDataStore } from '@/store/bookDataStore';
import { saveViewSettings } from '@/helpers/settings';
import { useAuth } from '@/context/AuthContext';
import { useSettingsStore } from '@/store/settingsStore';
import { useTranslation } from '@/hooks/useTranslation';
import { useTranslator } from '@/hooks/useTranslator';
import { TRANSLATOR_LANGS } from '@/services/constants';
import { isCustomTranslatorAllowed } from '@/utils/access';
import {
  UseTranslatorOptions,
  getTranslatorDisplayLabel,
  getTranslators,
  isTranslatorAvailable,
} from '@/services/translators';
import Select from '@/components/Select';

const notSupportedLangs = [''];

const generateTranslatorLangs = () => {
  return Object.fromEntries(
    Object.entries(TRANSLATOR_LANGS).filter(([code]) => !notSupportedLangs.includes(code)),
  );
};

const translatorLangs = generateTranslatorLangs();

interface TranslatorPopupProps {
  bookKey: string;
  text: string;
  position: Position;
  trianglePosition: Position;
  popupWidth: number;
  popupHeight: number;
  onDismiss?: () => void;
}

interface TranslatorType {
  name: string;
  label: string;
  disabled: boolean;
}

const TranslatorPopup: React.FC<TranslatorPopupProps> = ({
  bookKey,
  text,
  position,
  trianglePosition,
  popupWidth,
  popupHeight,
  onDismiss,
}) => {
  const _ = useTranslation();
  const { token } = useAuth();
  const { envConfig } = useEnv();
  const { getViewSettings } = useReaderStore();
  const { settings, setSettings } = useSettingsStore();
  const [providers, setProviders] = useState<TranslatorType[]>([]);
  const [sourceLang, setSourceLang] = useState(
    getViewSettings(bookKey)?.translateSourceLang ?? 'AUTO',
  );
  const [targetLang, setTargetLang] = useState(settings.globalReadSettings.translateTargetLang);
  const [provider, setProvider] = useState(settings.globalReadSettings.translationProvider);
  const [translation, setTranslation] = useState<string | null>(null);
  const [detectedSourceLang, setDetectedSourceLang] = useState<string | null>(null);

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  // The provider's own failure reason (HTTP status, upstream status code,
  // network error), shown under the generic message so a failure can be
  // diagnosed from the popup itself (#5823).
  const [errorDetail, setErrorDetail] = useState<string | null>(null);
  const book = useBookDataStore((s) => s.getBookData(bookKey)?.book);
  const { translate, translator, translators } = useTranslator({
    provider,
    sourceLang,
    targetLang,
    promptId: getViewSettings(bookKey)?.translationPromptId,
    bookTitle: book?.title,
    bookAuthor: book?.author,
  } as UseTranslatorOptions);

  const handleSourceLangChange = (event: React.ChangeEvent<HTMLSelectElement>) => {
    setSourceLang(event.target.value);
    saveViewSettings(envConfig, bookKey, 'translateSourceLang', event.target.value, true, false);
  };

  const handleTargetLangChange = (event: React.ChangeEvent<HTMLSelectElement>) => {
    settings.globalReadSettings.translateTargetLang = event.target.value;
    setSettings(settings);
    setTargetLang(event.target.value);
  };

  const handleProviderChange = (event: React.ChangeEvent<HTMLSelectElement>) => {
    const requestedProvider = event.target.value;
    const availableTranslators = getTranslators().filter((t) =>
      isTranslatorAvailable(t, !!token, isCustomTranslatorAllowed(token)),
    );
    const selectedTranslator =
      availableTranslators.find((t) => t.name === requestedProvider) || availableTranslators[0]!;
    if (selectedTranslator) {
      settings.globalReadSettings.translationProvider = selectedTranslator.name;
      setSettings(settings);
      setProvider(selectedTranslator.name);
    }
  };

  useEffect(() => {
    const hasPremium = isCustomTranslatorAllowed(token);
    const availableProviders = translators.map((t) => ({
      name: t.name,
      label: getTranslatorDisplayLabel(t, !!token, hasPremium, _),
      disabled: !!t.disabled || (!!t.premiumRequired && !hasPremium),
    }));
    setProviders(availableProviders);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [translators, token]);

  useEffect(() => {
    setLoading(true);
    const fetchTranslation = async () => {
      setError(null);
      setErrorDetail(null);
      setTranslation(null);

      try {
        const input = text.replaceAll('\n', '').trim();
        const result = await translate([input]);
        const translatedText = result[0];
        const detectedSource = null;

        if (!translatedText) {
          throw new Error('No translation found');
        }

        // Decode provider entities once while keeping any markup literal.
        const decoder = document.createElement('textarea');
        decoder.innerHTML = translatedText.replaceAll('<', '&lt;');
        setTranslation(decoder.value);
        if (sourceLang === 'AUTO' && detectedSource) {
          setDetectedSourceLang(detectedSource);
        }
      } catch (err) {
        console.error(err);
        // Only blame a missing login when this provider actually needs one;
        // Azure/Google/Yandex run without a Readest account in the app.
        if (translator?.authRequired && !token) {
          setError(_('Unable to fetch the translation. Please log in first and try again.'));
        } else {
          setError(_('Unable to fetch the translation. Try again later.'));
          setErrorDetail(err instanceof Error ? err.message : String(err));
        }
      } finally {
        setLoading(false);
      }
    };

    fetchTranslation();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [text, token, sourceLang, targetLang, provider, translate]);

  return (
    <div>
      <Popup
        trianglePosition={trianglePosition}
        width={popupWidth}
        minHeight={popupHeight}
        maxHeight={720}
        position={position}
        // Tracks are space-separated (`_` in a Tailwind arbitrary value).
        // Commas here emitted `grid-template-rows:1fr,auto,1fr,auto`, which the
        // browser discards, leaving four implicit auto rows that sized to their
        // content and pushed the translated pane and the provider footer past
        // the popup's own max height with nothing scrollable to reach them.
        // `minmax(0,...)` rather than a bare `1fr`: a bare fr floors at
        // min-content, so the rows would refuse to shrink inside the capped
        // popup and overflow it again.
        className='grid h-full select-text grid-rows-[minmax(0,1fr)_auto_minmax(0,1fr)_auto]'
        onDismiss={onDismiss}
      >
        <div className='overflow-y-auto p-4 font-sans'>
          <div className='mb-2 flex items-center justify-between'>
            <h1 className='text-sm font-medium'>{_('Original Text')}</h1>
            <Select
              value={sourceLang}
              onChange={handleSourceLangChange}
              options={[
                { value: 'AUTO', label: _('Auto Detect') },
                ...Object.entries(translatorLangs)
                  .sort((a, b) => a[1].localeCompare(b[1]))
                  .map(([code, name]) => {
                    const label =
                      detectedSourceLang && sourceLang === 'AUTO' && code === 'AUTO'
                        ? `${translatorLangs[detectedSourceLang] || detectedSourceLang} ` +
                          _('(detected)')
                        : name;
                    return { value: code, label };
                  }),
              ]}
            />
          </div>
          <p className='text-base'>{text}</p>
        </div>

        <div className='mx-4 shrink-0 border-t border-base-content/20'></div>

        <div className='overflow-y-auto p-4 font-sans'>
          <div className='mb-2 flex items-center justify-between'>
            <h2 className='text-sm font-medium'>{_('Translated Text')}</h2>
            <Select
              value={targetLang}
              onChange={handleTargetLangChange}
              options={[
                { value: '', label: _('System Language') },
                ...Object.entries(translatorLangs)
                  .sort((a, b) => a[1].localeCompare(b[1]))
                  .map(([code, name]) => ({ value: code, label: name })),
              ]}
            />
          </div>
          {loading ? (
            <p className='text-base-content/80 italic'>{_('Loading...')}</p>
          ) : (
            <div>
              {error ? (
                <div>
                  <p className='text-base text-red-600'>{error}</p>
                  {errorDetail && (
                    <p className='mt-1 break-words text-xs text-base-content/60'>{errorDetail}</p>
                  )}
                </div>
              ) : (
                <p className='text-base'>{translation || _('No translation available.')}</p>
              )}
            </div>
          )}
        </div>
        {/* No top border or tinted fill: the footer reads as part of the popup
            surface, so its provider select can sit flush on the same color. */}
        <div className='flex shrink-0 items-center justify-between gap-2 rounded-b-lg px-4 py-2'>
          <div className='line-clamp-1 text-xs text-base-content/60'>
            {provider &&
              !loading &&
              !error &&
              _('Translated by {{provider}}.', {
                provider: providers.find((p) => p.name === provider)?.label,
              })}
          </div>
          <Select
            value={provider}
            onChange={handleProviderChange}
            options={providers.map(({ name: value, label, disabled }) => ({
              value,
              label,
              disabled,
            }))}
          />
        </div>
      </Popup>
    </div>
  );
};

export default TranslatorPopup;
